        if insn.mnemonic=='lea' or (insn.mnemonic in ('mov','cmp','push') and 'rip' in insn.op_str):
            import re
            m = re.search(r'\[rip ([+-]) 0x([0-9a-f]+)\]', insn.op_str)
            if m:
